package org.asundr;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

import java.awt.*;

@ConfigGroup(TradeHighligherConfig.CONFIG_GROUP)
public interface TradeHighligherConfig extends Config
{
	String CONFIG_GROUP = "trade-highlighter";
	String KEY_DEFINITIONS = "definitions";
	String KEY_NON_GE_IDS = "nonGeIds";

	@ConfigSection(
			name = "General",
			description = "General settings",
			position = -10
	)
	String SECTION_GENERAL = "general";

	@ConfigSection(
			name = "Defaults",
			description = "Default values for newly added definitions",
			position = -9
	)
	String SECTION_DEFAULTS = "defaults";

	@ConfigSection(
			name = "Advanced",
			description = "Options for advanced users",
			position = 100
	)
	String SECTION_ADVANCED = "advanced";

	/////

	@ConfigItem(
		keyName = "enableOfferNotifications",
		name = "Enable offer notification",
		description = "If true, items that have been set to notify will do so once offered by the other player",
		section = SECTION_GENERAL
	)
	default boolean enableOfferNotifications() { return true; }

	@ConfigItem(
			keyName = "enableConfirmNotifications",
			name = "Enable confirm notification",
			description = "If true, you will be notified upon entering the trade confirmation window if the other player has offered any items set to notify",
			section = SECTION_GENERAL
	)
	default boolean enableConfirmNotifications() { return true; }

	@ConfigItem(
			keyName = "enableConfirmHighlight",
			name = "Enable confirm highlight",
			description = "If true, item names with highlight definitions offered by the other player in the trade confirmation window will be highlighted",
			section = SECTION_GENERAL
	)
	default boolean enableConfirmHighlight() { return true; }

	@ConfigItem(
			keyName = "enableOfferHighlight",
			name = "Enable offer highlight",
			description = "If true, items with highlight definitions offered by the other player in the trade confirmation window will be highlighted",
			section = SECTION_GENERAL
	)
	default boolean enableOfferHighlight() { return true; }

	@ConfigItem(
			keyName = "switchToDefinitionOnAdd",
			name = "Switch ot definition on add",
			description = "If true, automatically switches to definitions tab when new definition is added",
			section = SECTION_GENERAL
	)
	default boolean switchToDefinitionOnAdd() { return true; }

	@ConfigItem(
			keyName = "defaultColor",
			name = "Default color",
			description = "The default color set when adding a new highlight definition",
			section = SECTION_DEFAULTS
	)
	default Color defaultColor() { return Color.white; }

	@ConfigItem(
			keyName = "defaultNotify",
			name = "Default notify",
			description = "If enabled, any new definition with be set to notify by default",
			section = SECTION_DEFAULTS
	)
	default boolean defaultNotify() { return false; }

	@ConfigItem(
			keyName = KEY_NON_GE_IDS,
			name = "Custom item IDs",
			description = "Comma-separated list of item IDs that will allow those items to be added for highlighting." +
					"<br>Useful for new tradeable items that cannot be put in the GE that are not yet handled by the plugin." +
					"<br>Make an issue on the plugin's github page if this item should be handled by default.",
			section = SECTION_ADVANCED
	)
	default String getNonGeIds() { return ""; }
}

